sys_script_include.script:
var getExitData = Class.create();
getExitData.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
	getExit() {
		var emp = this.getParameter('sysparm_employee');
		gs.info('emp' + emp);
        var gr = new GlideRecord('x_594089_employe_0_exit_request');
        gr.addQuery('employee', emp);
        gr.query();

        if (gr.next()) {
            var result = {
				reason: gr.getValue('reason'),
                other_reason: gr.getValue('other_reason'),
                resignation_date: gr.getValue('resignation_date'),
                last_working_day: gr.getValue('last_working_day')
            };
			gs.info('gs.info(JSON.stringify(result));' + JSON.stringify(result));
            return JSON.stringify(result);
        }
        return JSON.stringify({});
	},
    type: 'getExitData'
});
